package vn.smartfarm.iot.irrigation;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.MockMvc;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest(properties={"spring.datasource.url=${SMARTFARM_TEST_DB_URL}","spring.flyway.schemas=telemetry_test","spring.flyway.default-schema=telemetry_test","smartfarm.mqtt.enabled=false","smartfarm.control.enabled=false","smartfarm.irrigation.demo-enabled=false","smartfarm.irrigation-queue.scheduling-enabled=false"})
@AutoConfigureMockMvc @EnabledIfEnvironmentVariable(named="SMARTFARM_TEST_DB_URL",matches=".+")
class IrrigationCircuitsTest {
 @Autowired IrrigationCircuits circuits;@Autowired IrrigationQueue queue;@Autowired JdbcTemplate jdbc;@Autowired ObjectMapper mapper;@Autowired MockMvc mvc;
 long pumps,runs,valves;String binding;
 @BeforeEach void setup(){cleanup();jdbc.update("INSERT INTO irrigation_demo_binding(singleton) VALUES(1) ON CONFLICT DO NOTHING");for(int i=1;i<=2;i++){
  jdbc.update("INSERT INTO iot_node(node_id,name,area_id,node_type,telemetry_version) VALUES(?,?,'AREA001','SOIL',2)","CSOIL"+i,"Soil "+i);
  jdbc.update("INSERT INTO irrigation_zone(zone_id,name,area_id,soil_node_id,expected_source,dry_threshold,wet_threshold) VALUES(?,?,'AREA001',?,'SIMULATOR',30,35)","CZONE"+i,"Vùng "+i,"CSOIL"+i);
  for(int c=1;c<=3;c++){jdbc.update("INSERT INTO iot_channel(node_id,channel_id,metric,unit) VALUES(?,?,'SOIL_MOISTURE','%')","CSOIL"+i,"SOIL"+c);jdbc.update("INSERT INTO irrigation_zone_channel(zone_id,node_id,channel_id,position) VALUES(?,?,?,?)","CZONE"+i,"CSOIL"+i,"SOIL"+c,c-1);}
  jdbc.update("INSERT INTO iot_node(node_id,name,area_id,node_type,telemetry_version) VALUES(?,?,'AREA001','WATER',2)","CWATER"+i,"Water "+i);
  jdbc.update("INSERT INTO iot_channel(node_id,channel_id,metric,unit) VALUES(?,'LOW','WATER_PRESENT','boolean'),(?,'FLOW','FLOW_RATE','L/min')","CWATER"+i,"CWATER"+i);
 }pumps=count("pump_command");runs=count("watering_run");valves=count("irrigation_demo_command");binding=jdbc.queryForObject("SELECT json_agg(r)::text FROM irrigation_demo_binding r",String.class);}
 void cleanup(){jdbc.update("DELETE FROM irrigation_queue_request WHERE zone_id IN ('CZONE1','CZONE2')");jdbc.update("DELETE FROM irrigation_circuit WHERE circuit_id LIKE 'CIR_TEST%'");jdbc.update("DELETE FROM irrigation_zone WHERE zone_id IN ('CZONE1','CZONE2')");jdbc.update("DELETE FROM iot_node WHERE node_id IN ('CSOIL1','CSOIL2','CWATER1','CWATER2','IRRIGATION02')");}
 @AfterEach void noDispatch(){try{assertEquals(pumps,count("pump_command"));assertEquals(runs,count("watering_run"));assertEquals(valves,count("irrigation_demo_command"));assertEquals(binding,jdbc.queryForObject("SELECT json_agg(r)::text FROM irrigation_demo_binding r",String.class));}finally{cleanup();}}
 long count(String table){return jdbc.queryForObject("SELECT COUNT(*) FROM "+table,Long.class);}
 ObjectNode config(int i){return mapper.createObjectNode().put("circuitId","CIR_TEST"+i).put("name","Nhánh "+i).put("zoneId","CZONE"+i).put("zoneRevision",1).put("controllerId","IRRIGATION02").put("valveId","VALVE0"+i).put("pumpId","PUMP01").put("waterNodeId","CWATER1").put("lowChannelId","LOW").put("flowChannelId","FLOW").put("expectedSource","SIMULATOR");}
 ObjectNode edit(int i){return (ObjectNode)mapper.valueToTree(circuits.find("CIR_TEST"+i));}
 ObjectNode request(int zone,boolean mapped){var r=mapper.createObjectNode().put("requestId",UUID.randomUUID().toString()).put("zoneId","CZONE"+zone).put("zoneRevision",1).put("durationSeconds",5).put("requestedAt",Instant.now().toString());if(mapped)r.put("circuitId","CIR_TEST"+zone).put("circuitRevision",1);return r;}
 IrrigationCircuits.View view(int i){return circuits.snapshot().circuits().stream().filter(c->c.config().circuitId().equals("CIR_TEST"+i)).findFirst().orElseThrow();}
 void water(boolean present,double flow,String source,int secondsOld,String quality){Long id=jdbc.queryForObject("INSERT INTO node_sample(node_id,boot_id,sequence,observed_at,received_at,uptime_ms,data_source) VALUES('CWATER1',?,1,?,?,1,?) RETURNING id",Long.class,UUID.randomUUID(),Timestamp.from(Instant.now().minusSeconds(secondsOld)),Timestamp.from(Instant.now().minusSeconds(secondsOld)),source);jdbc.update("INSERT INTO channel_sample(sample_id,node_id,channel_id,quality,boolean_value) VALUES(?,'CWATER1','LOW',?,?)",id,quality,quality.equals("VALID")?present:null);jdbc.update("INSERT INTO channel_sample(sample_id,node_id,channel_id,quality,number_value) VALUES(?,'CWATER1','FLOW',?,?)",id,quality,quality.equals("VALID")?flow:null);}

 @Test void multipleBranchesCanShareControllerPumpAndWaterButNotZoneOrValve(){circuits.create(config(1));circuits.create(config(2));assertEquals(2,circuits.snapshot().circuits().size());assertFalse(circuits.snapshot().dispatchAvailable());assertEquals("CONFIGURATION_ONLY",circuits.snapshot().mode());assertEquals("CURRENT",view(2).configurationState());assertEquals("NOT_CONNECTED",view(2).valveState());assertEquals("MISSING",view(1).low().state());assertThrows(Exception.class,()->circuits.create(config(1).put("circuitId","CIR_TEST3").put("valveId","VALVE03")));assertThrows(Exception.class,()->circuits.create(config(2).put("circuitId","CIR_TEST3").put("valveId","VALVE01")));}
 @Test void optimisticRevisionPreventsLostUpdate(){circuits.create(config(1));var body=edit(1).put("name","Đã sửa");assertEquals(2,circuits.update("CIR_TEST1",body).revision());assertThrows(Exception.class,()->circuits.update("CIR_TEST1",body.put("name","Ghi đè")));assertEquals("Đã sửa",circuits.find("CIR_TEST1").name());}
 @Test void zoneSourceRevisionAndChannelShapeMustMatch(){for(var b:List.of(config(1).put("zoneRevision",2),config(1).put("expectedSource","PHYSICAL"),config(1).put("waterNodeId","CSOIL1"),config(1).put("lowChannelId","FLOW"),config(1).put("flowChannelId","LOW")))assertThrows(Exception.class,()->circuits.create(b));assertEquals(0,count("irrigation_circuit"));}
 @Test void physicalConfigurationIsOnlyAPlanAndCannotEnterSimulatorQueue(){jdbc.update("UPDATE irrigation_zone SET expected_source='PHYSICAL' WHERE zone_id='CZONE1'");circuits.create(config(1).put("expectedSource","PHYSICAL"));assertEquals("NOT_CONNECTED",view(1).valveState());assertThrows(Exception.class,()->queue.enqueue(request(1,true)));}
 @Test void inventoryCollisionIsRejectedAndLaterCollisionMarksExistingPlan(){jdbc.update("INSERT INTO iot_node(node_id,name,area_id,node_type,telemetry_version) VALUES('IRRIGATION02','Conflict','AREA001','WATER',2)");assertThrows(Exception.class,()->circuits.create(config(1)));jdbc.update("DELETE FROM iot_node WHERE node_id='IRRIGATION02'");circuits.create(config(1));jdbc.update("INSERT INTO iot_node(node_id,name,area_id,node_type,telemetry_version) VALUES('IRRIGATION02','Later','AREA001','WATER',2)");assertEquals("IDENTITY_CONFLICT",view(1).configurationState());assertThrows(Exception.class,()->queue.enqueue(request(1,true)));}
 @Test void missingStaleFaultAndWrongSourceNeverClaimAvailable(){circuits.create(config(1));assertEquals("MISSING",view(1).low().state());water(true,1,"SIMULATOR",20,"VALID");assertEquals("STALE",view(1).low().state());water(true,1,"PHYSICAL",0,"VALID");assertEquals("SOURCE_MISMATCH",view(1).low().state());jdbc.update("DELETE FROM node_sample WHERE node_id='CWATER1'");water(true,0,"SIMULATOR",0,"SENSOR_FAULT");assertEquals("SENSOR_FAULT",view(1).flow().state());}
 @Test void freshZeroFlowAtRestIsValidAndLowIsIndependent(){circuits.create(config(1));water(false,0,"SIMULATOR",0,"VALID");assertEquals("LOW",view(1).low().state());assertEquals("FRESH",view(1).flow().state());jdbc.update("DELETE FROM node_sample WHERE node_id='CWATER1'");water(true,0,"SIMULATOR",-10,"VALID");assertEquals("CLOCK_SKEW",view(1).low().state());}
 @Test void healthTracksZoneAndChannelEditsWithoutMutatingSavedConfig(){circuits.create(config(1));jdbc.update("UPDATE irrigation_zone SET revision=2 WHERE zone_id='CZONE1'");assertEquals("ZONE_CHANGED",view(1).configurationState());assertEquals(1,circuits.find("CIR_TEST1").zoneRevision());circuits.update("CIR_TEST1",edit(1).put("zoneRevision",2));jdbc.update("UPDATE iot_channel SET metric='WATER_PRESSURE',unit='kPa' WHERE node_id='CWATER1' AND channel_id='FLOW'");assertEquals("WATER_DECLARATION_CHANGED",view(1).configurationState());}
 @Test void queueRequiresExplicitMappingReviewAndKeepsImmutableSnapshot(){circuits.create(config(1));assertThrows(Exception.class,()->queue.enqueue(request(1,false)));var req=request(1,true);var q=queue.enqueue(req);assertEquals("VALVE01",q.circuitSnapshot().path("valveId").asText());circuits.update("CIR_TEST1",edit(1).put("valveId","VALVE03").put("waterNodeId","CWATER2"));assertEquals(q.ticket(),queue.enqueue(req).ticket());assertThrows(Exception.class,()->queue.enqueue(req.deepCopy().put("circuitRevision",2)));assertThrows(Exception.class,()->queue.rehearse(q.requestId(),queue.snapshot().revision()));queue.maintainAt(Instant.now());assertEquals("INVALIDATED",queue.lookup(q.requestId()).state());assertEquals("CIRCUIT_CHANGED",queue.lookup(q.requestId()).reason());assertEquals("VALVE01",queue.lookup(q.requestId()).circuitSnapshot().path("valveId").asText());}
 @Test void mappingAddedAfterUnmappedRequestRequiresNewReview(){var q=queue.enqueue(request(1,false));assertNull(q.circuitSnapshot());circuits.create(config(1));assertThrows(Exception.class,()->queue.rehearse(q.requestId(),queue.snapshot().revision()));queue.maintainAt(Instant.now());assertEquals("CIRCUIT_CHANGED",queue.lookup(q.requestId()).reason());assertNull(queue.lookup(q.requestId()).circuitSnapshot());}
 @Test void mappingEditInterruptsActiveWithoutAdvancingNext(){circuits.create(config(1));circuits.create(config(2));var a=queue.enqueue(request(1,true));var b=queue.enqueue(request(2,true));queue.rehearse(a.requestId(),queue.snapshot().revision());circuits.update("CIR_TEST1",edit(1).put("valveId","VALVE03"));queue.maintainAt(Instant.now());assertEquals("INTERRUPTED",queue.lookup(a.requestId()).state());assertEquals("CIRCUIT_CHANGED",queue.lookup(a.requestId()).reason());assertEquals("QUEUED",queue.lookup(b.requestId()).state());assertNull(queue.snapshot().active());}
 @Test void competingSavesCannotAssignOneValveTwice()throws Exception{var gate=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->{gate.await();try{circuits.create(config(1));return true;}catch(Exception e){return false;}});var b=pool.submit(()->{gate.await();try{circuits.create(config(2).put("valveId","VALVE01"));return true;}catch(Exception e){return false;}});gate.countDown();assertNotEquals(a.get(5,TimeUnit.SECONDS),b.get(5,TimeUnit.SECONDS));}assertEquals(1,count("irrigation_circuit"));}
 @Test void httpRejectsMalformedExtraAndPartialReview()throws Exception{String api="/api/v1/irrigation-circuits";for(String b:List.of("{}","[]","{\"name\":1,\"name\":2}",config(1)+"{}",config(1).put("extra",true).toString(),config(1).put("valveId","VALVE00").toString(),config(1).put("pumpId","PUMP02").toString()))mvc.perform(post(api).contentType("application/json").content(b)).andExpect(status().isBadRequest());circuits.create(config(1));mvc.perform(post("/api/v1/irrigation-queue/requests").contentType("application/json").content(request(1,false).put("circuitId","CIR_TEST1").toString())).andExpect(status().isBadRequest());}
 @Test void httpCreateEditConflictAndReadAreConfigurationOnly()throws Exception{String api="/api/v1/irrigation-circuits";mvc.perform(post(api).contentType("application/json").content(config(1).toString())).andExpect(status().isCreated()).andExpect(jsonPath("$.revision").value(1));var old=edit(1);mvc.perform(put(api+"/CIR_TEST1").contentType("application/json").content(old.toString())).andExpect(status().isOk()).andExpect(jsonPath("$.revision").value(2));mvc.perform(put(api+"/CIR_TEST1").contentType("application/json").content(old.toString())).andExpect(status().isConflict());mvc.perform(post(api).contentType("application/json").content(config(2).put("valveId","VALVE01").toString())).andExpect(status().isConflict());long before=circuits.snapshot().revision();mvc.perform(get(api)).andExpect(status().isOk()).andExpect(jsonPath("$.dispatchAvailable").value(false));assertEquals(before,circuits.snapshot().revision());mvc.perform(get(api+"/UNKNOWN")).andExpect(status().isNotFound());}
 @Test void upgradeFromV25PreservesOldQueueWithoutInventingMapping(){String schema="circuit_upgrade_"+UUID.randomUUID().toString().replace("-","");try{
  org.flywaydb.core.Flyway.configure().dataSource(jdbc.getDataSource()).schemas(schema).defaultSchema(schema).target("25").load().migrate();
  jdbc.update("INSERT INTO "+schema+".iot_node(node_id,name,area_id,node_type,telemetry_version) VALUES('CSOIL1','Old soil','AREA001','SOIL',2)");
  jdbc.update("INSERT INTO "+schema+".irrigation_zone(zone_id,name,area_id,soil_node_id,expected_source,dry_threshold,wet_threshold) VALUES('CZONE1','Old zone','AREA001','CSOIL1','SIMULATOR',30,35)");
  UUID id=UUID.randomUUID();jdbc.update("INSERT INTO "+schema+".irrigation_queue_request(request_id,zone_id,zone_revision,zone_snapshot,duration_seconds,requested_at,enqueued_at,expires_at,state,reason) VALUES(?,'CZONE1',1,'{}',5,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP+INTERVAL '5 minutes','QUEUED','WAITING')",id);
  String before=jdbc.queryForObject("SELECT row_to_json(q)::text FROM "+schema+".irrigation_queue_request q",String.class);
  org.flywaydb.core.Flyway.configure().dataSource(jdbc.getDataSource()).schemas(schema).defaultSchema(schema).load().migrate();
  try{assertEquals(mapper.readTree(before),mapper.readTree(jdbc.queryForObject("SELECT (to_jsonb(q)-'circuit_snapshot')::text FROM "+schema+".irrigation_queue_request q",String.class)));}catch(Exception e){throw new AssertionError(e);}
  assertNull(jdbc.queryForObject("SELECT circuit_snapshot FROM "+schema+".irrigation_queue_request",String.class));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM "+schema+".irrigation_circuit",Integer.class));
 }finally{jdbc.execute("DROP SCHEMA IF EXISTS "+schema+" CASCADE");}}
}
